import{dotProduct4,qmul,RaymarchApplet}from"/scripts/applets/raymarchApplet.min.js";import{animate}from"/scripts/src/utils.min.js";class QuaternionicJuliaSets extends RaymarchApplet{showCrossSection=!1;constructor({canvas,xrFramebufferScaleSlider}){super({canvas:canvas,distanceEstimatorGlsl:`
			vec4 z = vec4(pos, 0.0);
			vec4 zPrime = vec4(1.0, 0.0, 0.0, 0.0);
			float r;
			
			for (int iteration = 0; iteration < 16; iteration++)
			{
				r = length(z);
				
				if (r > 16.0)
				{
					break;
				}
				
				zPrime = 2.0 * qmul(z, zPrime);
				
				z = qmul(z, z);
				
				z += mix(vec4(pos, 0.0), vec4(c, 0.0), juliaProportion);
			}
			
			
			r = length(z);
			float juliaSetDistance = .5 * r * log(r) / length(zPrime);

			// The 1.5 is an experimental factor for the minimum radius sphere that still fits all the julia sets we draw
			return max(juliaSetDistance, dot(pos - normalVector * planeTranslation * 1.35, normalVector));
		`,getColorGlsl:`
			vec4 z = vec4(pos, 0.0);
			vec4 zPrime = vec4(1.0, 0.0, 0.0, 0.0);
			float r;
			
			vec3 color = vec3(1.0, 1.0, 1.0);
			float colorScale = .5;
			
			for (int iteration = 0; iteration < 8; iteration++)
			{
				r = length(z);
				
				if (r > 16.0)
				{
					break;
				}
				
				zPrime = 2.0 * qmul(z, zPrime);
				
				z = qmul(z, z);
				
				z += mix(vec4(pos, 0.0), vec4(c, 0.0), juliaProportion);
				
				color = mix(color, abs(normalize(z.xyz)), colorScale);
				
				colorScale *= .5;
			}
			
			color /= max(max(color.x, color.y), color.z);
			
			return color;
		`,addGlsl:`
			vec4 qmul(vec4 z, vec4 w)
			{
				return vec4(z.x*w.x - z.y*w.y - z.z*w.z - z.w*w.w, z.x*w.y + z.y*w.x + z.z*w.w - z.w*w.z, z.x*w.z - z.y*w.w + z.z*w.x + z.w*w.y, z.x*w.w + z.y*w.z - z.z*w.y + z.w*w.x);
			}
		`,uniformsGlsl:`
			uniform vec3 c;
			uniform vec3 normalVector;
			uniform float planeTranslation;
			uniform float juliaProportion;
		`,uniforms:{c:[-.54,-.25,-.668],normalVector:[0,-.9864,.1643],planeTranslation:1,juliaProportion:1},epsilonScalingFactor:.65,surfaceNormalEpsilonFactor:.5,stepFactor:.75,theta:1.269,phi:1.98,sceneOrigin:[-1.033,-3.316,1.506],lightPos:[-5,-5,5],lightBrightness:1.2,overstepFactor:1.6,coneMarchingScale:12,useGradientCorrectedOcclusion:!0,xrFramebufferScaleSlider:xrFramebufferScaleSlider})}distanceEstimator(x,y,z){var r=this.uniforms.c,o=this.uniforms.juliaProportion;let t=[x,y,z,0],e=[1,0,0,0],a=0;for(let i=0;i<16&&!(16<(a=Math.sqrt(dotProduct4(t,t))));i++)(e=qmul(...t,...e))[0]*=2,e[1]*=2,e[2]*=2,e[3]*=2,(t=qmul(...t,...t))[0]+=(1-o)*x+o*r[0],t[1]+=(1-o)*y+o*r[1],t[2]+=(1-o)*z+o*r[2];return.5*Math.log(a)*a/Math.sqrt(dotProduct4(e,e))}switchBulb(instant){var r=this.uniforms.juliaProportion;if(Math.floor(r)===r){const o=r,e=1-r;animate(t=>{this.setUniforms({juliaProportion:(1-t)*o+t*e}),this.needNewFrame=!0},instant?0:750,"easeInOutQuad")}}}export{QuaternionicJuliaSets};